/* ---------- sections you add yourself ---------- */
function buildCustom(sc){
  const el=document.createElement("section");el.className="s";el.id=sc.id;
  el.innerHTML=`<div class="wrap"><h2></h2><p class="lede"></p><div class="seg" id="ctabs-${esc(sc.id)}" role="tablist"></div><div class="cgrid" id="clist-${esc(sc.id)}"></div></div>`;
  return el;
}
function renderCustom(sc){
  const items=((DATA.custom||{})[sc.id]||[]);
  const cats=catNames(sc.id,()=>[...new Set(items.map(i=>i.cat).filter(Boolean))]);
  let cur="All";
  const tabsEl=$("#ctabs-"+sc.id),list=$("#clist-"+sc.id);
  const draw=()=>{
    if(cats.length)tabs(tabsEl,[["All","All",items.length],...cats.map(c=>[c,c,items.filter(i=>i.cat===c).length])],cur,v=>{cur=v;draw()});
    else tabsEl.hidden=true;
    const shown=items.filter(i=>cur==="All"||i.cat===cur);
    list.innerHTML=shown.length?shown.map(i=>`<article class="ccard fade">${i.image?`<img src="${esc(i.image)}" alt="" loading="lazy">`:""}<div class="cbody2"><h3>${fmt(i.title||"")}</h3>${i.subtitle?`<div class="csub">${fmt(i.subtitle)}</div>`:""}${i.text?`<p>${fmt(i.text)}</p>`:""}${i.link&&!isTodo(i.link)?`<a class="sm" href="${esc(href(i.link))}" target="_blank" rel="noopener">${ICON.ext}${esc(i.linkText||"Open")}</a>`:""}</div></article>`).join(""):`<div class="empty-note">Nothing added here yet.</div>`;
  };
  draw();
}

/* ---------- order, names and visibility of the main sections ---------- */
function applyLayout(){
  const cfg=(Array.isArray(DATA.sections)&&DATA.sections.length?DATA.sections:DEFAULT_DATA.sections).slice();
  DEFAULT_DATA.sections.forEach(d=>{if(!cfg.some(x=>x.id===d.id))cfg.push(Object.assign({},d))});
  const main=$("main"),out=[["top","Home"]];
  cfg.forEach(sc=>{
    let el=document.getElementById(sc.id),fresh=false;
    if(!el&&sc.custom){el=buildCustom(sc);fresh=true}
    if(!el)return;
    main.appendChild(el);
    const h=$("h2",el),l=$(".lede",el);
    if(h&&sc.title)h.textContent=sc.title;
    if(l&&sc.lede!=null){l.textContent=sc.lede;l.hidden=!sc.lede}
    const vis=sc.visible!==false;el.hidden=!vis;
    if(fresh)renderCustom(sc);
    if(vis)out.push([sc.id,sc.nav||sc.title||sc.id]);
  });
  return out;
}

