/* ---------- experience ---------- */
/*XP-START*/
const MONTHS=["January","February","March","April","May","June","July","August","September","October","November","December"];
const DAY=864e5;
function parseD(s,asEnd){
  const m=/^(\d{4})(?:-(\d{2})(?:-(\d{2}))?)?$/.exec(String(s||"").trim());if(!m)return null;
  const y=+m[1],mo=m[2]?+m[2]:(asEnd?12:1);
  let d=m[3]?+m[3]:1;
  if(!m[3]&&asEnd)d=new Date(Date.UTC(y,mo,0)).getUTCDate();      // a month or a year alone ends on its last day
  const t=new Date(Date.UTC(y,mo-1,d));return isNaN(t)?null:t;
}
function todayUTC(){const n=new Date();return new Date(Date.UTC(n.getFullYear(),n.getMonth(),n.getDate()))}
const isPresent=e=>!e||/^present$/i.test(String(e).trim());
function jobSpan(j){const a=parseD(j.start,false),e=isPresent(j.end)?todayUTC():parseD(j.end,true);return a&&e&&e>=a?{a,e}:null}
function ymd(a,b){
  let y=b.getUTCFullYear()-a.getUTCFullYear(),m=b.getUTCMonth()-a.getUTCMonth(),d=b.getUTCDate()-a.getUTCDate();
  if(d<0){m--;d+=new Date(Date.UTC(b.getUTCFullYear(),b.getUTCMonth(),0)).getUTCDate()}
  if(m<0){y--;m+=12}
  return {y,m,d};
}
const spanYMD=sp=>ymd(sp.a,new Date(sp.e.getTime()+DAY));
function mergeSpans(list){
  const out=[];
  list.slice().sort((x,y)=>x.a-y.a).forEach(sp=>{
    const last=out[out.length-1];
    if(last&&sp.a.getTime()<=last.e.getTime()+DAY)last.e=new Date(Math.max(last.e.getTime(),sp.e.getTime()));
    else out.push({a:sp.a,e:sp.e});
  });
  return out;
}
function totalYMD(spans){
  let y=0,m=0,d=0;
  mergeSpans(spans).forEach(sp=>{const t=spanYMD(sp);y+=t.y;m+=t.m;d+=t.d});
  m+=Math.floor(d/30);d%=30;y+=Math.floor(m/12);m%=12;
  return {y,m,d};
}
const plural=(n,w)=>`${n} ${w}${n===1?"":"s"}`;
const fmtYMD=t=>`${plural(t.y,"Year")}, ${plural(t.m,"Month")}, ${plural(t.d,"Day")}`;
const fmtDate=d=>`${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
/*XP-END*/
const fmtStr=(s,d)=>/^\d{4}$/.test(s)?s:/^\d{4}-\d{2}$/.test(s)?`${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`:fmtDate(d);
function periodText(j){const sp=jobSpan(j);if(!sp)return `${fmt(j.start)} to ${fmt(j.end)}`;return `${fmtStr(String(j.start).trim(),sp.a)} to ${isPresent(j.end)?"Present":fmtStr(String(j.end).trim(),sp.e)}`}
function durText(j){const sp=jobSpan(j);return sp?fmtYMD(spanYMD(sp)):""}
function renderXp(list){
  const box=$("#xpBox");
  if(!list.length||list.every(j=>j.noTotal)){box.hidden=true;return}
  box.hidden=false;
  const label=expType==="All"?"Total work experience":expType+" experience";
  const spans=list.filter(j=>!j.noTotal).map(jobSpan).filter(Boolean);
  const t=spans.length?totalYMD(spans):(expType==="All"?DATA.experienceFallback:null);
  if(!t){box.innerHTML=`<div class="lbl">${label}</div><div class="fb">Dates needed</div>`;return}
  box.innerHTML=`<div class="lbl">${label}</div><div class="ymd"><div><b>${t.y}</b><span>${t.y===1?"Year":"Years"}</span></div><div><b>${t.m}</b><span>${t.m===1?"Month":"Months"}</span></div><div><b>${t.d}</b><span>${t.d===1?"Day":"Days"}</span></div></div>`;
}
let expType="All";
function renderExp(){
  const types=["All",...catNames("experience",()=>["Full-time","Part-time"])];
  const cnt=t=>t==="All"?DATA.experience.length:DATA.experience.filter(j=>j.type===t).length;
  tabs($("#expTabs"),types.map(t=>[t,t,cnt(t)]),expType,v=>{expType=v;renderExp()});
  const list=DATA.experience.filter(j=>expType==="All"||j.type===expType);
  renderXp(list);
  $("#jobs").innerHTML=list.length?list.map((j,i)=>
   `<article class="job fade ${i===0?"open":""}" data-tags="${j.tags.join(" ")}">
     <button type="button" aria-expanded="${i===0}" aria-controls="jp${i}">
       <span><h3>${fmt(j.role)}</h3><span class="badge">${esc(j.type)}</span>
         <span class="org">${fmt(j.org)}</span>
         <span class="meta">${periodText(j)}, ${fmt(j.location)}</span></span>
       ${durText(j)||isTodo(j.start)||isTodo(j.end)?`<span class="dur ${durText(j)?"":"off"}">${durText(j)||"Add dates"}</span>`:""}
       <span class="chev">${ICON.chev}</span>
     </button>
     <div class="panel" id="jp${i}"><div ${i===0?"":"inert"}>
       <p class="sum">${fmt(j.summary)}</p>
       <dl class="dl">
         ${j.website?`<div><dt>Company website</dt><dd>${linkOrTodo(j.website)}</dd></div>`:""}
         <div><dt>Period</dt><dd>${periodText(j)}</dd></div>
         ${durText(j)?`<div><dt>Duration</dt><dd>${durText(j)}</dd></div>`:""}
         ${j.location?`<div><dt>Location</dt><dd>${fmt(j.location)}</dd></div>`:""}
         ${j.email?`<div><dt>Office email</dt><dd>${mailOrTodo(j.email)}</dd></div>`:""}
       </dl>
       <h4>Responsibilities</h4>
       <ul>${j.points.map(p=>`<li>${fmt(p)}</li>`).join("")}</ul>
     </div></div>
   </article>`).join(""):`<div class="empty-note">No ${esc(expType.toLowerCase())} roles added yet.</div>`;
  $$(".job > button").forEach(b=>b.addEventListener("click",()=>{
    const job=b.parentElement,open=!job.classList.contains("open");
    job.classList.toggle("open",open);b.setAttribute("aria-expanded",String(open));
    const inner=$(".panel > div",job);if(open)inner.removeAttribute("inert");else inner.setAttribute("inert","");
  }));
  applyTag();
}
renderExp();
