let refType="All",refTimer=null,refPer=0,refIO=null,refRO=null;
const REF_INT=5000;
const refCard=r=>{
  const pl=r.profile||r.linkedin||r.website||"";
  const name=pl&&!isTodo(pl)?`<a class="refname" href="${esc(href(pl))}" target="_blank" rel="noopener">${fmt(r.name)}${ICON.ext}</a>`:fmt(r.name);
  const org=r.org?(r.orgWebsite&&!isTodo(r.orgWebsite)?`<a class="orglink" href="${esc(href(r.orgWebsite))}" target="_blank" rel="noopener">${fmt(r.org)}${ICON.ext}</a>`:fmt(r.org)):"";
  return `<article class="ref ${r.type==="Academic"?"academic":""}">
     <h3>${name}</h3>
     ${r.position?`<div class="pos">${fmt(r.position)}</div>`:""}
     ${org?`<div class="org">${org}</div>`:""}
     ${r.location?`<div class="ln"><em>Location</em><span>${fmt(r.location)}</span></div>`:""}
     ${r.email?`<div class="ln"><em>Email</em><span>${mailOrTodo(r.email)}${isTodo(r.email)?"":" "+cpBtn(r.email,"Email address copied")}</span></div>`:""}
   </article>`;
};
function renderRefs(){
  clearTimeout(refTimer);
  const all=DATA.references,types=catNames("references",()=>["Professional","Academic"]);
  tabs($("#refTabs"),[["All","All",all.length],...types.map(t=>[t,t,all.filter(r=>r.type===t).length])],refType,v=>{refType=v;renderRefs()});
  const list=all.filter(r=>refType==="All"||r.type===refType),box=$("#refBox"),n=list.length;
  if(!n){box.innerHTML=`<div class="empty-note">No references added here yet.</div>`;return}
  const per=box.clientWidth>=700?2:1,maxPos=Math.max(0,n-per);refPer=per;
  box.innerHTML=(maxPos?`<div class="rprog"><i></i></div>`:"")+`<div class="rfvp fade"><div class="rftrack" style="--per:${per}">${list.map(r=>`<div class="rfslide">${refCard(r)}</div>`).join("")}</div></div>`+
    (maxPos?`<div class="rctl"><button type="button" class="sm rfp" aria-label="Previous reference">${ICON.left}Previous</button><div class="dots">${Array.from({length:maxPos+1},(_,k)=>`<i class="${k===0?"on":""}" data-k="${k}"></i>`).join("")}</div><button type="button" class="sm rfn" aria-label="Next reference">Next${ICON.right}</button></div>`:"");
  if(!maxPos)return;
  const track=$(".rftrack",box),bar=$(".rprog i",box);let k=0,hover=false,visible=false;
  const run=()=>{clearTimeout(refTimer);bar.classList.remove("run");if(hover||!visible||document.hidden)return;void bar.offsetWidth;bar.classList.add("run");refTimer=setTimeout(()=>go(k>=maxPos?0:k+1),REF_INT)};
  const go=to=>{k=Math.max(0,Math.min(maxPos,to));track.style.transform=`translateX(${-k*100/per}%)`;$$(".dots i",box).forEach((d,x)=>d.classList.toggle("on",x===k));run()};
  $(".rfp",box).addEventListener("click",()=>go(k<=0?maxPos:k-1));
  $(".rfn",box).addEventListener("click",()=>go(k>=maxPos?0:k+1));
  $$(".dots i",box).forEach(d=>d.addEventListener("click",()=>go(+d.dataset.k)));
  box.onmouseenter=()=>{hover=true;run()};box.onmouseleave=()=>{hover=false;run()};
  box.onfocusin=()=>{hover=true;run()};box.onfocusout=()=>{hover=false;run()};
  if(refIO)refIO.disconnect();
  refIO=new IntersectionObserver(e=>{visible=e[0].isIntersecting;run()},{threshold:.25});refIO.observe(box);
}
renderRefs();
if("ResizeObserver" in window){
  refRO=new ResizeObserver(()=>{const w=$("#refBox").clientWidth;if(w&&(w>=700?2:1)!==refPer)renderRefs()});
  refRO.observe($("#refBox"));
}
document.addEventListener("visibilitychange",()=>{if(!document.hidden&&refPer)renderRefs()});

/* ---------- gallery ---------- */
function ph(cat,ratio,k){
  const [w,h]=ratio.split("/").map(Number),W=400,H=Math.round(400*h/w);
  const col={Research:"#1B6B62",Work:"#2F5D8A",Foundation:"#8A6A1F",Events:"#6B4A7A",Videos:"#2A3F5F"}[cat]||"#1B6B62";
  const o=(k||0)*.07;
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}"><rect width="${W}" height="${H}" fill="${col}"/><g stroke="#fff" stroke-opacity=".28" fill="none" stroke-width="2"><path d="M0 ${H*(.3+o)}H${W*.4}L${W*.5} ${H*(.45+o)}H${W}"/><path d="M${W*(.2+o)} ${H}V${H*.7}L${W*.35} ${H*.6}H${W}"/><circle cx="${W*.4}" cy="${H*(.3+o)}" r="6"/><circle cx="${W*.35}" cy="${H*.6}" r="6"/></g><text x="50%" y="52%" text-anchor="middle" fill="#fff" fill-opacity=".9" font-family="sans-serif" font-size="20">${cat==="Videos"?"":"Your photo here"}</text></svg>`;
  return "data:image/svg+xml;charset=utf-8,"+encodeURIComponent(svg);
}
const photoSrc=(g,k)=>g.photos[k].src||ph(g.cat,"4/3",k);
function ytId(u){const m=String(u).match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?(?:.*&)?v=|embed\/|shorts\/|live\/))([A-Za-z0-9_-]{11})/);return m?m[1]:null}
let galCat="All",galView=[],lastVideo=null;
const videoList=g=>Array.isArray(g.videos)&&g.videos.length?g.videos.filter(v=>v&&!v.off):(g.url?[{url:g.url,caption:""}]:[]);
function posterHTML(g,v,k){
  const id=isTodo(v.url)?null:ytId(v.url),fb=ph("Videos","16/9",k);
  return `<button type="button" class="poster" aria-label="Play video: ${esc(plain(v.caption||g.title))}"><img src="${id?`https://i.ytimg.com/vi/${id}/hqdefault.jpg`:fb}" data-fb="${fb}" alt="" loading="lazy" draggable="false"><span class="pbtn">${ICON.play}</span></button>`;
}
function vcap(v){
  const todo=isTodo(v.url),id=todo?null:ytId(v.url);
  return (v.caption?fmt(v.caption)+" ":"")+(todo?fmt("[[YouTube link needed]]"):(id?`<a class="v" href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener">Open on YouTube</a>`:"This YouTube link looks invalid."));
}
function frameHTML(g,i){
  if(g.type==="video"){
    const vids=videoList(g);if(!vids.length)vids.push({url:"",caption:""});
    const n=vids.length;
    return `<figure class="frame video fade" data-i="${i}">
      <div class="vp vid"><div class="track">${vids.map((v,k)=>`<div class="vslide" data-k="${k}">${posterHTML(g,v,k)}</div>`).join("")}</div>
        ${n>1?`<button type="button" class="nav prev" aria-label="Previous video">${ICON.left}</button><button type="button" class="nav next" aria-label="Next video">${ICON.right}</button><span class="count">1 / ${n}</span>`:""}
      </div>
      <figcaption class="fc"><b>${fmt(g.title)}</b><span class="cp">${vcap(vids[0])}</span>${n>1?`<div class="dots">${vids.map((_,k)=>`<i class="${k===0?"on":""}"></i>`).join("")}</div>`:""}</figcaption></figure>`;
  }
  const n=g.photos.length;
  return `<figure class="frame fade" data-i="${i}">
    <div class="vp">
      <div class="track">${g.photos.map((p,k)=>`<button type="button" class="slide" data-k="${k}" aria-label="Enlarge photo ${k+1} of ${n}"><img src="${photoSrc(g,k)}" alt="${esc(plain(p.caption||g.title))}" draggable="false" loading="lazy"></button>`).join("")}</div>
      ${n>1?`<button type="button" class="nav prev" aria-label="Previous photo">${ICON.left}</button><button type="button" class="nav next" aria-label="Next photo">${ICON.right}</button><span class="count">1 / ${n}</span>`:""}
    </div>
    <figcaption class="fc"><b>${fmt(g.title)}</b><span class="cp">${fmt(g.photos[0].caption||"")}</span>
      ${n>1?`<div class="dots">${g.photos.map((_,k)=>`<i class="${k===0?"on":""}"></i>`).join("")}</div>`:""}</figcaption>
  </figure>`;
}
function wireFrame(fig,g){
  if(g.type==="video"){
    const vids=videoList(g);if(!vids.length)vids.push({url:"",caption:""});
    const n=vids.length,vp=$(".vp",fig),track=$(".track",fig),slides=$$(".vslide",fig);
    const posters=slides.map(s=>s.innerHTML);let k=0,sx=null,swiped=false;
    const bind=x=>{
      const s=slides[x];
      $$("img[data-fb]",s).forEach(im=>im.addEventListener("error",()=>{if(im.src!==im.dataset.fb)im.src=im.dataset.fb},{once:true}));
      const b=$(".poster",s);if(!b)return;
      b.addEventListener("click",()=>{
        if(swiped){swiped=false;return}
        const v=vids[x];
        if(isTodo(v.url)){toast("Add the YouTube link first");return}
        const id=ytId(v.url);if(!id){toast("That YouTube link looks invalid");return}
        s.innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${id}?autoplay=1&rel=0&playsinline=1" title="${esc(plain(v.caption||g.title))}" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><button type="button" class="vclose" aria-label="Close video">×</button>`;
        lastVideo={vp:s,id};
        $(".vclose",s).addEventListener("click",()=>{s.innerHTML=posters[x];bind(x)});
      });
    };
    slides.forEach((_,x)=>bind(x));
    const go=to=>{
      slides.forEach((s,x)=>{if(s.querySelector("iframe,.blocked")){s.innerHTML=posters[x];bind(x)}});   // stop a playing video when you move on
      k=(to+n)%n;track.style.transform=`translateX(${-100*k}%)`;
      const c=$(".count",fig);if(c)c.textContent=`${k+1} / ${n}`;
      $(".cp",fig).innerHTML=vcap(vids[k]);
      $$(".dots i",fig).forEach((d,i)=>d.classList.toggle("on",i===k));
    };
    if(n>1){
      $(".prev",fig).addEventListener("click",()=>go(k-1));
      $(".next",fig).addEventListener("click",()=>go(k+1));
      vp.addEventListener("pointerdown",e=>{sx=e.clientX;swiped=false});
      vp.addEventListener("pointerup",e=>{if(sx==null)return;const dx=e.clientX-sx;sx=null;if(Math.abs(dx)>40){swiped=true;go(k+(dx<0?1:-1))}});
      vp.addEventListener("pointercancel",()=>{sx=null});
    }
    return;
  }
  const n=g.photos.length,track=$(".track",fig);let k=0;
  function go(to){
    k=(to+n)%n;track.style.transform=`translateX(${-100*k}%)`;
    const c=$(".count",fig);if(c)c.textContent=`${k+1} / ${n}`;
    $(".cp",fig).innerHTML=fmt(g.photos[k].caption||"");
    $$(".dots i",fig).forEach((d,x)=>d.classList.toggle("on",x===k));
  }
  if(n>1){
    $(".prev",fig).addEventListener("click",e=>{e.stopPropagation();go(k-1);fig._at=Date.now()+8000});
    $(".next",fig).addEventListener("click",e=>{e.stopPropagation();go(k+1);fig._at=Date.now()+8000});
    fig._next=()=>go(k+1);
  }
  const vp=$(".vp",fig);let sx=null,swiped=false;
  if(n>1){
    vp.addEventListener("pointerdown",e=>{sx=e.clientX;swiped=false});
    vp.addEventListener("pointerup",e=>{if(sx==null)return;const dx=e.clientX-sx;sx=null;if(Math.abs(dx)>40){swiped=true;go(k+(dx<0?1:-1));fig._at=Date.now()+8000}});
    vp.addEventListener("pointercancel",()=>{sx=null});
  }
  $$(".slide",fig).forEach(s=>s.addEventListener("click",()=>{if(swiped){swiped=false;return}openLb(g,+s.dataset.k)}));
}
function renderGal(){
  const cats=catNames("gallery",()=>[...new Set(DATA.gallery.map(g=>g.cat))]);
  tabs($("#galTabs"),[["All","All",DATA.gallery.length],...cats.map(c=>[c,c,DATA.gallery.filter(g=>g.cat===c).length])],galCat,v=>{galCat=v;renderGal()});
  galView=DATA.gallery.filter(g=>galCat==="All"||g.cat===galCat);
  $("#galGrid").innerHTML=galView.map(frameHTML).join("");
  $$("#galGrid .frame").forEach((fig,i)=>wireFrame(fig,galView[i]));
}
