/* lightbox */
const lb=$("#lb");let lbG=null,lbK=0,lbX=null;
$("#lbPrev").innerHTML=ICON.left;$("#lbNext").innerHTML=ICON.right;
function showLb(){
  const n=lbG.photos.length,p=lbG.photos[lbK];
  $("#lbImg").src=photoSrc(lbG,lbK);$("#lbImg").alt=plain(p.caption||lbG.title);
  $("#lbCount").textContent=`${plain(lbG.title)}: ${lbK+1} of ${n}`;
  $("#lbCap").textContent=plain(p.caption||"");
  $("#lbPrev").style.display=$("#lbNext").style.display=n>1?"":"none";
}
