lw.addEventListener("pointerdown",e=>{lbX=e.clientX});
lw.addEventListener("pointerup",e=>{if(lbX==null)return;const dx=e.clientX-lbX;lbX=null;if(Math.abs(dx)>50&&lbG.photos.length>1)lbStep(dx<0?1:-1)});

